// One row per keyword: this week vs. last week, period average, peak and rising queries.
const items = $input.all().map(i => i.json);
const timelines = items.filter(i => i.type === 'interestOverTime');
if (timelines.length === 0) throw new Error('No interestOverTime result. Check the Apify run log.');

const avg = a => (a.length ? a.reduce((s, v) => s + v, 0) / a.length : null);
const r1 = v => (v === null || Number.isNaN(v) ? '' : Math.round(v * 10) / 10);
const reportDate = $now.toFormat('yyyy-MM-dd');
const rows = [];

for (const t of timelines) {
  const points = (t.timeline || []).filter(p => !p.isPartial);
  const stepDays = points.length > 1 ? (points[1].time - points[0].time) / 86400 : 7;
  const win = Math.max(1, Math.round(7 / stepDays)); // data points per week (7 for daily, 1 for weekly data)
  for (const kw of t.keywords) {
    const series = points.map(p => Number(p.values[kw] ?? 0));
    const thisWeek = avg(series.slice(-win));
    const lastWeek = avg(series.slice(-2 * win, -win));
    const peak = points[series.indexOf(Math.max(...series))];
    const related = items.find(i => i.type === 'relatedQueries' && i.keyword === kw) || {};
    rows.push({ json: {
      report_date: reportDate,
      keyword: kw,
      geo: t.geo,
      this_week: r1(thisWeek),
      last_week: r1(lastWeek),
      change_pct: lastWeek ? r1(((thisWeek - lastWeek) / lastWeek) * 100) : '',
      period_avg: r1(t.averages && t.averages[kw] !== undefined ? t.averages[kw] : avg(series)),
      peak: peak ? peak.formattedTime : '',
      rising_queries: (related.rising || []).slice(0, 5).map(q => `${q.query} (${q.formattedValue})`).join(', '),
    } });
  }
}
return rows;
